	["Damage Chunk"] = "Trozo de daño", -- draft
	["The part of the bar a hit took stays lit for a moment before it drains, so you see each hit's size."] = "La parte de la barra que se llevó un golpe queda iluminada un momento antes de vaciarse, para ver el tamaño de cada golpe.", -- draft
	["Crit Glow"] = "Brillo crítico", -- draft
