	-- Tooltip
	["Tooltip"] = "Descripción", -- draft
	["Dark flat tooltips with class coloured names and borders, plus placement options."] = "Descripciones oscuras y planas con nombres y bordes del color de la clase, además de opciones de colocación.", -- draft
	["Dark, flat and out of the way, with names in the colour of their class."] = "Oscuras, planas y discretas, con los nombres del color de su clase.", -- draft
	["Background"] = "Fondo", -- draft
	["The tooltips' background: Dark, the game's own, or (with Oldschool) Painted or Parchment."] = "El fondo de las descripciones: Oscuro, el del juego o (con Oldschool) Pintado o Pergamino.", -- draft
